import type * as Workers from '@cloudflare/workers-types';

// Import binding types without replacing the DOM Request/Response types used
// by the Next.js browser application. Env itself is generated by wrangler.
declare global {
  type D1Database = Workers.D1Database;
  type Fetcher = Workers.Fetcher;
  type Service<T extends Workers.ExportedHandler | undefined = undefined> = Workers.Service<T>;
  type ImagesBinding = Workers.ImagesBinding;
  type DurableObjectNamespace<T extends Workers.DurableObject | undefined = undefined> = Workers.DurableObjectNamespace<T>;
  type ExecutionContext = Workers.ExecutionContext;
  type IncomingRequestCfProperties = Workers.IncomingRequestCfProperties;
}
